-- Tabela: pedido_pagamentos
DROP TABLE IF EXISTS `pedido_pagamentos`;

CREATE TABLE `pedido_pagamentos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `pedido_id` int NOT NULL,
  `valor` decimal(10,2) NOT NULL,
  `forma_pagamento` enum('dinheiro','cartao_debito','cartao_credito','pix','prazo') COLLATE utf8mb4_unicode_ci NOT NULL,
  `valor_recebido` decimal(10,2) DEFAULT NULL COMMENT 'Valor entregue pelo cliente (dinheiro), para cálculo de troco',
  `valor_troco` decimal(10,2) DEFAULT NULL,
  `conta_receber_id` int DEFAULT NULL COMMENT 'Preenchido quando forma_pagamento = prazo',
  `observacoes` text COLLATE utf8mb4_unicode_ci,
  `usuario_id` int NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pedido_id` (`pedido_id`),
  KEY `idx_conta_receber_id` (`conta_receber_id`),
  KEY `idx_created_at` (`created_at`),
  KEY `usuario_id` (`usuario_id`),
  CONSTRAINT `pedido_pagamentos_ibfk_1` FOREIGN KEY (`pedido_id`) REFERENCES `pedidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pedido_pagamentos_ibfk_2` FOREIGN KEY (`conta_receber_id`) REFERENCES `contas_receber` (`id`),
  CONSTRAINT `pedido_pagamentos_ibfk_3` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Histórico de pagamentos (parciais ou totais) de cada pedido';


-- Tabela: pedidos
DROP TABLE IF EXISTS `pedidos`;

CREATE TABLE `pedidos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_pedido` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `origem` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'pdv',
  `total` decimal(10,2) NOT NULL,
  `valor_pago` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'Soma dos pagamentos já registrados',
  `status` enum('aberto','parcial','finalizado','cancelado') COLLATE utf8mb4_unicode_ci DEFAULT 'aberto',
  `tipo_pedido` enum('balcao','entrega') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'balcao' COMMENT 'Tipo do pedido',
  `endereco_entrega` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Endere├ºo de entrega',
  `taxa_entrega` decimal(10,2) DEFAULT '0.00' COMMENT 'Taxa de entrega aplicada',
  `zona_entrega_id` int DEFAULT NULL COMMENT 'ID da zona de entrega',
  `forma_pagamento` enum('dinheiro','cartao_debito','cartao_credito','pix','prazo') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `troco_para` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `cliente_id` int DEFAULT NULL,
  `cliente_nome` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cliente_telefone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_cliente` enum('avulso','cadastrado') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'avulso',
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero_pedido` (`numero_pedido`),
  KEY `idx_cliente_id` (`cliente_id`),
  KEY `idx_tipo_cliente` (`tipo_cliente`),
  KEY `idx_tipo_pedido` (`tipo_pedido`),
  KEY `idx_zona_entrega` (`zona_entrega_id`)
) ENGINE=InnoDB AUTO_INCREMENT=236 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Tabela: pedidos_itens_adicionais
DROP TABLE IF EXISTS `pedidos_itens_adicionais`;

CREATE TABLE `pedidos_itens_adicionais` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_id` int NOT NULL,
  `adicional_id` int NOT NULL,
  `quantidade` int NOT NULL,
  `preco` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `item_id` (`item_id`),
  KEY `adicional_id` (`adicional_id`),
  CONSTRAINT `pedidos_itens_adicionais_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `pedido_itens` (`id`),
  CONSTRAINT `pedidos_itens_adicionais_ibfk_2` FOREIGN KEY (`adicional_id`) REFERENCES `adicionais` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Tabela pedidos_itens_adicionais vazia

-- Tabela: permissions
DROP TABLE IF EXISTS `permissions`;

CREATE TABLE `permissions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nome` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descricao` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `modulo` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Módulo do sistema',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nome` (`nome`),
  KEY `idx_nome` (`nome`),
  KEY `idx_modulo` (`modulo`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Tabela: produtos
DROP TABLE IF EXISTS `produtos`;

CREATE TABLE `produtos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nome` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descricao` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `imagem` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nome do arquivo de imagem (ex: sorvete-chocolate.jpg)',
  `preco` decimal(10,2) NOT NULL,
  `categoria_id` int NOT NULL,
  `ativo` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `categoria_id` (`categoria_id`),
  CONSTRAINT `produtos_ibfk_1` FOREIGN KEY (`categoria_id`) REFERENCES `categorias` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Tabela: rate_limits
DROP TABLE IF EXISTS `rate_limits`;

CREATE TABLE `rate_limits` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ip` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Endereço IP',
  `action` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ação realizada (login, api_call, etc)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ip_action_time` (`ip`,`action`,`created_at`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Controle de rate limiting por IP';

-- Tabela rate_limits vazia

-- Tabela: recibos
DROP TABLE IF EXISTS `recibos`;

CREATE TABLE `recibos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `numero_recibo` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `serie` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'A',
  `cliente_id` int NOT NULL,
  `pagamento_id` int DEFAULT NULL,
  `usuario_id` int NOT NULL,
  `valor_recebido` decimal(15,2) DEFAULT NULL,
  `valor_desconto` decimal(15,2) DEFAULT '0.00',
  `valor_juros` decimal(15,2) DEFAULT '0.00',
  `valor_multa` decimal(15,2) DEFAULT '0.00',
  `valor_liquido` decimal(15,2) NOT NULL,
  `descricao` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `referencia` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `data_emissao` date NOT NULL,
  `data_vencimento_original` date DEFAULT NULL,
  `data_pagamento` date NOT NULL,
  `forma_pagamento` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `banco` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agencia` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `conta` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cheque` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `observacoes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` enum('ativo','cancelado') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ativo',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `conta_receber_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero_recibo` (`numero_recibo`),
  KEY `idx_numero_recibo` (`numero_recibo`),
  KEY `idx_cliente_id` (`cliente_id`),
  KEY `idx_pagamento_id` (`pagamento_id`),
  KEY `idx_data_emissao` (`data_emissao`),
  KEY `idx_data_pagamento` (`data_pagamento`),
  KEY `idx_status` (`status`),
  KEY `recibos_ibfk_4` (`usuario_id`),
  KEY `idx_conta_receber_id` (`conta_receber_id`),
  CONSTRAINT `recibos_ibfk_1` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`),
  CONSTRAINT `recibos_ibfk_3` FOREIGN KEY (`pagamento_id`) REFERENCES `pagamentos` (`id`),
  CONSTRAINT `recibos_ibfk_4` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


